#include "host_dx12/ffx_flow/ffx_flow_shaders.hpp"

#if defined(NA_HAVE_FFX_FLOW)
// Generated by DXC into the build folder (never committed). Each defines
// `const unsigned char na_ffx_of_<pass>_hdr<0|1>[]`.
#include "na_ffx_of_prepare_luma_hdr0.h"
#include "na_ffx_of_prepare_luma_hdr1.h"
#include "na_ffx_of_luminance_pyramid_hdr0.h"
#include "na_ffx_of_luminance_pyramid_hdr1.h"
#include "na_ffx_of_scd_histogram_hdr0.h"
#include "na_ffx_of_scd_histogram_hdr1.h"
#include "na_ffx_of_scd_divergence_hdr0.h"
#include "na_ffx_of_scd_divergence_hdr1.h"
#include "na_ffx_of_search_hdr0.h"
#include "na_ffx_of_search_hdr1.h"
#include "na_ffx_of_filter_hdr0.h"
#include "na_ffx_of_filter_hdr1.h"
#include "na_ffx_of_scale_hdr0.h"
#include "na_ffx_of_scale_hdr1.h"
#endif

namespace na::ffx_flow {

namespace {
#if defined(NA_HAVE_FFX_FLOW)
#define NA_FFX_BLOB(x) Blob{x, sizeof(x)}
const Blob kBlobs[static_cast<int>(Pass::Count)][2] = {
    {NA_FFX_BLOB(na_ffx_of_prepare_luma_hdr0), NA_FFX_BLOB(na_ffx_of_prepare_luma_hdr1)},
    {NA_FFX_BLOB(na_ffx_of_luminance_pyramid_hdr0), NA_FFX_BLOB(na_ffx_of_luminance_pyramid_hdr1)},
    {NA_FFX_BLOB(na_ffx_of_scd_histogram_hdr0), NA_FFX_BLOB(na_ffx_of_scd_histogram_hdr1)},
    {NA_FFX_BLOB(na_ffx_of_scd_divergence_hdr0), NA_FFX_BLOB(na_ffx_of_scd_divergence_hdr1)},
    {NA_FFX_BLOB(na_ffx_of_search_hdr0), NA_FFX_BLOB(na_ffx_of_search_hdr1)},
    {NA_FFX_BLOB(na_ffx_of_filter_hdr0), NA_FFX_BLOB(na_ffx_of_filter_hdr1)},
    {NA_FFX_BLOB(na_ffx_of_scale_hdr0), NA_FFX_BLOB(na_ffx_of_scale_hdr1)},
};
#undef NA_FFX_BLOB
#endif
}  // namespace

Blob Shader(Pass pass, bool hdr) {
    const int i = static_cast<int>(pass);
    if (i < 0 || i >= static_cast<int>(Pass::Count)) return {};
#if defined(NA_HAVE_FFX_FLOW)
    return kBlobs[i][hdr ? 1 : 0];
#else
    (void)hdr;
    return {};
#endif
}

bool Built() {
#if defined(NA_HAVE_FFX_FLOW)
    return true;
#else
    return false;
#endif
}

const char* PassName(Pass pass) {
    switch (pass) {
        case Pass::PrepareLuma: return "prepare_luma";
        case Pass::LuminancePyramid: return "luminance_pyramid";
        case Pass::ScdHistogram: return "scd_histogram";
        case Pass::ScdDivergence: return "scd_divergence";
        case Pass::Search: return "search";
        case Pass::Filter: return "filter";
        case Pass::Scale: return "scale";
        default: return "?";
    }
}

}  // namespace na::ffx_flow
